{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Pronk_db_Product_FACEBOOK_CONSOLIDATED_intermediate AS select Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,\'Facebook Pronk Meta\' as Account_Name ,Account_ID ,Campaign_Name ,Campaign_ID ,REGEXP_EXTRACT(fb.product_id, r\'^([^,]+)\') AS product_id ,REGEXP_EXTRACT(fb.product_id, r\',\s*(.*)$\') AS product_name ,cast(Fb.date_start as date) Date ,SUM(CLICKS) Clicks ,sum(ifnull(inline_link_clicks,0)) Link_Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(ifnull(Fc.Conversions,0)) Conversions ,sum(ifnull(reach,0)) reach ,sum(ifnull(frequency,0)) as frequency ,SUM(ifnull(Fcv.Conversion_Value,0)) Conversion_Value ,sum(ifnull(fd.add_to_carts,0)) Add_to_carts ,sum(ifnull(fdv.add_to_cart_value,0)) Add_to_cart_value ,sum(ifnull(fe.landing_page_views,0)) Landing_page_views ,sum(ifnull(ff.initiate_checkouts,0)) Initiate_checkouts ,sum(ifnull(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'Facebook\' Channel ,\'Facebook_Custom_Facebook_Marketing_Pronk_db_Meta\' Account from( select * from maplemonk.Pronk_facebook_ads___product_customcampaigns_data ) FB left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.1d_view\') as FLOAT64),0)) Conversions from maplemonk.Custom_Facebook_Marketing_pronk_facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.1d_view\') as FLOAT64),0)) Conversion_Value from maplemonk.Custom_Facebook_Marketing_pronk_facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) add_to_carts from maplemonk.Custom_Facebook_Marketing_pronk_facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Add_to_cart_Value from maplemonk.Custom_Facebook_Marketing_pronk_facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from maplemonk.Custom_Facebook_Marketing_pronk_facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Initiate_checkouts from maplemonk.Custom_Facebook_Marketing_pronk_facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Initiate_checkouts_Value from maplemonk.Custom_Facebook_Marketing_pronk_facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start GROUP BY Adset_Name, Adset_ID, fb.ad_id, fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Fb.date_start, REGEXP_EXTRACT(fb.product_id, r\'^([^,]+)\'), REGEXP_EXTRACT(fb.product_id, r\',\s*(.*)$\'); CREATE OR REPLACE TABLE maplemonk.Pronk_db_Product_FACEBOOK_CONSOLIDATED as SELECT a.product_id AS PRODUCT_ID, DATE, \'FACEBOOK\' AS Channel, \'FACEBOOK ADS\' AS ACCOUNT, coalesce(p.sku, v.sku) AS SKU, coalesce(a.product_name, p.product_name_final, v.product_name_final) as product_name_final, coalesce(p.category, v.category) AS PRODUCT_CATEGORY, SUM(spend) AS SPEND, sum(conversion_value) AS SALES from maplemonk.Pronk_db_Product_FACEBOOK_CONSOLIDATED_intermediate a left join ( SELECT product_id, LOWER(TRIM(sku_code)) AS SKU, PRODUCT_NAME_Final, category from `maplemonk.PRONK_SHOPIFY_FACT_ITEMS` QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(product_id)) ORDER BY DATE(order_timestamp) DESC) = 1 ) p ON LOWER(REGEXP_REPLACE(a.product_id, r\'^-+|-+$\', \'\')) = LOWER(REGEXP_REPLACE(p.product_id, r\'^-+|-+$\', \'\')) left join ( SELECT variant_id, LOWER(TRIM(sku_code)) AS SKU, PRODUCT_NAME_Final, category FROM `maplemonk.PRONK_SHOPIFY_FACT_ITEMS` QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(variant_id)) ORDER BY DATE(order_timestamp) DESC) = 1 ) v ON LOWER(REGEXP_REPLACE(a.product_id, r\'^-+|-+$\', \'\')) = LOWER(REGEXP_REPLACE(v.variant_id, r\'^-+|-+$\', \'\')) group by 1,2,3,4,5,6,7",
                    "transaction": true
                }
            ) }}
